import { getCustomer } from './customers.js';
import { invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';
import { ok } from './result.js';

/**
 * Generate a customer statement.
 * @param {string} customerId
 * @param {Array} invoices
 * @param {string} asOf - YYYY-MM-DD date
 * @returns {object}
 */
export function statement(customerId, invoices, asOf) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  // Filter and map invoices
  const filteredInvoices = invoices
    .filter(inv =>
      inv.customerId === customerId &&
      (inv.status === 'issued' || inv.status === 'partially_paid') &&
      inv.issueDate <= asOf
    )
    .map(inv => ({
      number: inv.number,
      issueDate: inv.issueDate,
      dueDate: inv.dueDate,
      total: invoiceTotals(inv).total,
      due: balanceDue(inv),
    }))
    .sort((a, b) => a.issueDate.localeCompare(b.issueDate));

  const totalDue = filteredInvoices.reduce((sum, inv) => sum + inv.due, 0);

  return ok({
    customerId,
    invoices: filteredInvoices,
    totalDue,
  });
}

